function PVPArenaPlayerReadyDialogOld:InitBattleRoundData()
    self.battleRoundData = {}
    local battleRounds   = pvpArenaComponent:GetBattleRounds()
    for i = 1, battleRounds, 1 do
        table.insert(self.battleRoundData, -1)
    end
end

function PVPArenaPlayerReadyDialogOld:UpdateBattleRoundData(args)
    local result = checkBool(args.isWin) and 1 or 0
    local battleRoundData = self.battleRoundData
    local curRound = 0
    for i, v in ipairs(battleRoundData) do
        if v == -1 then
            curRound = i
            battleRoundData[i] = result
            break
        end
    end

    local battleResult = false
    ---写死判断了 
    if curRound == 2 then
        battleResult = battleRoundData[1] ~= battleRoundData[2]
    elseif curRound > 2 then
        battleResult = false
    else
        battleResult = true
    end

    if battleResult == false then
        self:DestroyView()
        pvpArenaComponent:SetPVPArenaLoadingEnv(nil)
    end

    return battleResult
end


