function PVPArenaPlayerReadyDialogOld:RefreshUI(data)
    local playerId      = data.playerId
    local playerInfo    = data.playerInfo
    local rivalInfo     = data.rivalInfo
    local rivalPlayerId = data.rivalPlayerId

    self:RefreshBasePlayerInfo(self.PanelL.gameObject, playerInfo, playerId)
    self:RefreshBasePlayerInfo(self.PanelR.gameObject, rivalInfo,  rivalPlayerId)

    local roundOfNumber = pvpArenaComponent:GetRoundOfNumber()
    if pvpArenaComponent:GetRoundOfNumberIsNum() then
        self.TxtNumber.text = roundOfNumber
    else
        self.Text.text = ""
        self.Txtranking.text = roundOfNumber
    end

