end

function PVPArenaPlayerReadyDialogOld:RefreshBasePlayerInfo(gameObject, info, playerId)
    ---@type PVPArenaBasePlayerInfo
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaBasePlayerInfoPath)
    if isNull(env) then return end
    env:RefreshUI(info, playerId, true)
end

function PVPArenaPlayerReadyDialogOld:Progress(value)
    KTool.SetActive(self.controller.gameObject, true)
    value = checkNumber(value) / 100
    value = math.min(value, 1)
    local rivalValue = value - 0.01 * math.random(1, 3)
    rivalValue = value == 1 and 1 or math.min(rivalValue, 1)

    self.SliderL.value = value
    self.SliderR.value = rivalValue

    local num = math.modf(checkInt(math.min(value*100, 100)))
    local numText = string.format("%s%%", num)
    self.SliderRTxtNumber.text = numText

    num = math.modf(checkInt(math.min(rivalValue*100, 100)))
    numText = string.format("%s%%", num)
    self.SliderLTxtNumber.text = numText
end


function PVPArenaPlayerReadyDialogOld:DestroyView()
    Application.backgroundLoadingPriority = ThreadPriority.BelowNormal
    CS.UnityEngine.GameObject.Destroy(self.controller.gameObject, 1)

end

function PVPArenaPlayerReadyDialogOld:Close()
    Application.backgroundLoadingPriority = ThreadPriority.BelowNormal
    KTool.SetActive(self.controller.gameObject, false)
end

function PVPArenaPlayerReadyDialogOld:EnterBattle()
    if self.isEnterBattle then return end
    self.isEnterBattle = true
    KTool.SetActive(self.Time.gameObject, false)
    KTool.SetActive(self.ReadyGroupR.gameObject, true)
    KTool.SetActive(self.SliderL.gameObject, true)
    KTool.SetActive(self.SliderR.gameObject, true)
    self.TimeGroup:Play(GoAniHash)

    --- 移除倒计时
    self:RemoveEventCountDownUpdate()

    cs_coroutine.start(function()
        local time = os.time()
        local isQuit = false
        while pvpArenaComponent:GetBattleServer() == nil do
            cs_coroutine.yield_return()
            if (os.time() - time) > TimeOutSeconds then
                isQuit = true
                break
            end
        end

        if isQuit then
            printError("未发现战斗服务器")
            self:DestroyView()
            --KTool.SafeDelete(self.controller.gameObject)
            return
        end

        xTry(function()

            ---1. 清掉当前所有的ui
            local co = GameUtils.CloseAllShowDialog(true)
            if co then
                cs_coroutine.yield_return(co)
            end

            --- 2. 将ui page 中的 记录移动到 BattleSelection
            local pages = UIModule.Instance.uiPages
            if pages.Count > 2 then
                UIModule.RemoveRecordToCustomDialog(Constants.UITypeIds.BattleSelection)
            end
            UIModule.AddUIPage({id = Constants.UITypeIds.PVPArenaMain, parameters = { isFromEntry = true }})

            --- 3. 释放建筑
            -- pvpArenaComponent:ReleaseMansion()
            pvpArenaComponent:ReleaseResources()
            
            --- 4. 设置loadingEnv
            pvpArenaComponent:SetPVPArenaLoadingEnv(self)

            --- 5. 进入战斗
            

            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
            -- if checkInt(self.loadingType) == Constants.LoadingType.Battle then
            UINavigationBarRoot.Instance:SetActive(false)
            ---去战斗的情况
            UIModule.StoreStackState(self.args)
            ---关闭所有的窗口
            -- local coWait = CoWait.Start()
            -- for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
            --     coWait:Coroutine(UIModule.CloseDialog(v, true))
            -- end
            -- while not coWait.IsFinish do
            --     coroutine.yield()
            -- end
            ---开始加载战斗场景
            xpcall(function ()
                KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
                local battleServer   = pvpArenaComponent:GetBattleServer()
                ---@type FightPreWarMgr
                local fightPreWarMgr = FightPreWarMgr:GetInstance()
                fightPreWarMgr:InitPVPParams({server = battleServer, gameMode = Constants.GameMode.PVP, pvpMode = Constants.PVPMode.Arena})
                BattleViewMgr:Start()
            end, function(err)
                print(err)
                printError(tostring(err))
            end)
            -- end
        end)

    end)

    --
    -----TODO 进入战斗
    --pvpArenaComponent:EnterBattle()
end

