function PVPArenaPlayerReadyDialogOld:OnEventCountDownUpdate()

    if self.inCountDown == nil then return end

    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local battleStatus = checkNumber(pvpArenaEntryDojo.battleStatus)
    local battleNextStageLeftSeconds = checkNumber(pvpArenaEntryDojo.battleNextStageLeftSeconds)
    if battleStatus == Constants.PVPArenaBattleStatus.Prepare and battleNextStageLeftSeconds > 0 then
        --- 更新倒计时
        self.TxtCountdownNumber.text = battleNextStageLeftSeconds
    else
        self.inCountDown = nil

        --- 只要不是 战前准备 继续加载 加载战斗 异常情况 从战斗走结算
        -- KTool.SetActive(self.ButtonReadyL.gameObject, false)
        -- KTool.SetActive(self.ReadyGroupL.gameObject, true)

        ---自己准备,对手未准备 --->> 对手判负  自己未准备,对手准备 --->> 自己判负
        ---拉home 并关闭界面
        --self:EnterBattle()
        self:ForcedQuit()
    end
end

function PVPArenaPlayerReadyDialogOld:OnEventCommonError()
    self.isForcedQuit = true
    self:ForcedQuit()
end

function PVPArenaPlayerReadyDialogOld:ForcedQuit()
    self:DestroyView()
    pvpArenaComponent:RequestHome()
end

function PVPArenaPlayerReadyDialogOld:OnEventRivalReady()
    if not self.isReady then return end
    self:EnterBattle()

end

function PVPArenaPlayerReadyDialogOld:OnClickButtonReadyAction()
    AppService:GetInstance():SendTcpData(Constants.Packets.PVPArenaSendPlayerReady)
    self.isReady = true
    self.ImgReadyLogo:Play(ShowAniHash)
    KTool.SetActive(self.ButtonReadyL.gameObject, false)
    KTool.SetActive(self.ReadyGroupL.gameObject, true)

    ---@type PVPArenaDojo
    local pvpArenaDojo    = pvpArenaComponent:GetPVPArenaDojo()
    local battleRound     = checkNumber(pvpArenaDojo.battleRound)
    --- 当前战斗轮数 等于 敌方准备的战斗轮数
    if  battleRound == pvpArenaComponent:GetRivalMatchRound() and 
    --- 敌方已准备
        pvpArenaComponent:GetRivalReadyState() then
        self:EnterBattle()
    end
end

